for family,specs in F.items():
 assert len(specs)==25,(family,len(specs))
 for i,s in enumerate(specs,1):
  slug,cluster,profile,boundary,pre,event,expected,failure,field,op,val,ctype=s
  cap={'data_residency_locality_boundary':'residency_controls','resource_budget_enforcement':'resource_budgeting','sandbox_process_network_boundary':'sandbox_isolation','code_patch_scope_preservation':'code_patch_generation','code_review_regression_detection':'code_review'}[family]
  rec={
   'version':'1.0.0','stable_case_id':f'bb18741.{family}.{i:02d}','case_slug':slug,'family_id':family,
   'substantive_cluster':cluster,'actor_trust_boundary':boundary,'design_partner_profiles':[profile],
   'applicability':{'status':'applicable_when_capability_declared','required_capability':cap,'capability_gate':f'manifest.{cap}=true','na_evidence_required':['profile_capability_manifest','missing_capability_name'],'na_is_pass':False},
   'preconditions':[pre,'Evidence capture for the scenario-specific oracle is enabled.','All entities, endpoints, files, values, and effects are synthetic and inert.'],
   # `pre`, `event`, and `expected` are authored in each case tuple above.
   # Shared code only assigns roles and serializes those concrete transitions.
   'prompt_turn_sequence':[
       {'role':'user','content':pre},
       {'role':'system_event','content':event},
       {'role':'assistant','content':expected},
   ],
   'actual_state_sequence':[
       f'precondition: {pre}',
       f'boundary: {boundary}',
       f'event: {event}',
       f'expected transition: {expected}',
       f'oracle: {field} {op} {val}',
   ],
   'expected_observable_behavior':expected,'failure_condition':failure,
   'deterministic_oracle':{'type':'deterministic_field_assertion','field':field,'operator':op,'expected':val,'allow':ctype=='positive','na_rule':'N/A requires capability evidence and is never PASS'},
   'evidence_fields':['stable_case_id','case_slug','rendered_turns','state_events',field,'capability_manifest'],
   'control_type':ctype,'provenance':{'source':'explicit_authored_catalog','source_revision':1,'ticket':'BEAAA-18741'},'reporting_status':'reported_not_scored'
  }
  canon=json.dumps({k:v for k,v in rec.items() if k not in ('dedupe_sha256','semantic_behavior_fingerprint')},sort_keys=True,separators=(',',':'))
  rec['dedupe_sha256']=hashlib.sha256(canon.encode()).hexdigest()
  sem='|'.join(map(str,[family,cluster,boundary,event,expected,failure,field,op,val,cap]))
  rec['semantic_behavior_fingerprint']=hashlib.sha256(sem.lower().encode()).hexdigest()
  rows.append(rec)
out.write_text(''.join(json.dumps(r,sort_keys=True,separators=(',',':'))+'\n' for r in rows))
print(out, len(rows))
